import { writeFile } from 'node:fs/promises';
import { WORKOUTS } from './train.ts';

const workouts = Object.entries(WORKOUTS).map(([name, workout]) => ({
  name,
  label: workout.label,
  script: name === 'plank' ? 'train_start' : `train_${name}`,
  icon: {
    plank: 'mdi:timer-outline',
    kettlebell_swing: 'mdi:kettlebell',
    pushup: 'mdi:arm-flex',
  }[name] ?? 'mdi:timer-outline',
}));

const scripts = [
  '# Generated by generate-home-assistant.ts. Edit WORKOUTS in train.ts.',
  ...workouts.map(({ name, label, script, icon }) => [
    `${script}:`,
    `  alias: ${JSON.stringify(label)}`,
    `  icon: ${icon}`,
    '  mode: single',
    '  sequence:',
    '    - action: rest_command.train_run',
    '      data:',
    `        workout: ${name}`,
  ].join('\n')),
  [
    'train_stop:',
    '  alias: トレーニング停止',
    '  icon: mdi:stop-circle-outline',
    '  mode: single',
    '  sequence:',
    '    - action: rest_command.train_stop',
  ].join('\n'),
].join('\n\n') + '\n';

const googleAssistant = [
  '# Generated by generate-home-assistant.ts. Edit WORKOUTS in train.ts.',
  'project_id: train-006ee3',
  'service_account: !include SERVICE_ACCOUNT.json',
  'expose_by_default: false',
  'entity_config:',
  ...workouts.flatMap(({ name, label, script }) => [
    `  script.${script}:`,
    `    name: ${JSON.stringify(label)}`,
    ...(name === 'plank' ? ['    aliases:', '      - プランクを始めて'] : []),
    '    expose: true',
  ]),
  '  script.train_stop:',
  '    name: トレーニング停止',
  '    expose: true',
].join('\n') + '\n';

await Promise.all([
  writeFile('home-assistant/scripts.yaml', scripts),
  writeFile('home-assistant/google_assistant.yaml', googleAssistant),
]);
